<script lang="ts">
  import {onMount} from 'svelte';import {request,displayTimestamp} from '#lib/client/api.ts';import Icon from './Icon.svelte';
  let reference=$state('');let personName=$state('');let email=$state('');let statement=$state('');let confirmed=$state(false);let busy=$state(false);let downloading=$state(false);let receiptNotice=$state('');let error=$state('');let receipt:any=$state(null);let key=$state('');
  onMount(()=>key=crypto.randomUUID());
  async function send(event:SubmitEvent){event.preventDefault();if(!confirmed||busy||!key)return;busy=true;error='';try{receipt=await request('/api/v1/withdrawal',{reference,person_name:personName,email,statement,idempotencyKey:key});}catch(e){error=e instanceof Error?e.message:'Die Erklärung konnte nicht übermittelt werden. Ihre Eingaben bleiben für einen erneuten Versuch erhalten.';}finally{busy=false;}}
  async function downloadReceipt(){if(!receipt?.id||!receipt?.receiptToken||downloading)return;downloading=true;receiptNotice='';error='';try{const response=await fetch(`/api/v1/withdrawal/receipts/${encodeURIComponent(receipt.id)}?token=${encodeURIComponent(receipt.receiptToken)}`,{credentials:'same-origin',cache:'no-store'});if(!response.ok){const body=await response.json().catch(()=>null);if(response.status===409&&body?.error?.code==='RECEIPT_PENDING'){receiptNotice='Der PDF-Eingangsnachweis wird noch erstellt. Ihre Erklärung ist bereits eingegangen. Sie können den Beleg in Kürze erneut abrufen oder diese Bestätigung jetzt drucken.';return;}throw new Error(body?.error?.message||'Der Eingangsnachweis konnte nicht geladen werden. Bitte versuchen Sie es erneut.');}const url=URL.createObjectURL(await response.blob());const link=document.createElement('a');link.href=url;link.download='Schubert-Eingangsnachweis.pdf';link.dataset.sveltekitReload='true';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e){error=e instanceof Error?e.message:'Der Eingangsnachweis konnte nicht geladen werden. Ihre Erklärung bleibt gespeichert.';}finally{downloading=false;}}
</script>
<div class="portal-shell"><header class="portal-topbar"><a class="brand" href="/login"><div class="brand-name">SCHUBERT</div><div class="brand-sub">DESIGN SUITE</div></a><span class="small muted">Ohne Portal-Anmeldung erreichbar</span></header><main class="withdrawal-content"><div class="page-heading"><div><h1>Widerruf übermitteln</h1><p>Sie können Ihre Erklärung auch abgeben, wenn Ihr Portalzugang nicht mehr verfügbar ist.</p></div></div>{#if receipt}<section class="panel"><div class="panel-body"><div class="notice info" role="status"><Icon name="check"/><div><strong>Ihre Erklärung ist eingegangen.</strong><p class="mt">{receipt.message||'Der Eingang wurde gespeichert und wird dem bezeichneten Vorgang zur Bearbeitung zugeordnet.'}</p></div></div>{#if receipt.reference||receipt.id}<p class="small mt">Eingangsreferenz: <strong>{receipt.reference||receipt.id}</strong></p>{/if}<p class="small mt">Die Eingangsbestätigung dokumentiert Ihre Übermittlung. Sie nimmt die weitere Bearbeitung und Prüfung Ihres Vertrags nicht vorweg.</p><dl class="definition-list mt"><div><dt>Vertrag / Vorgang</dt><dd>{reference}</dd></div><div><dt>Erklärt von</dt><dd>{personName}</dd></div><div><dt>Eingegangen</dt><dd>{displayTimestamp(receipt.received_at)}</dd></div></dl><p class="small mt" style="white-space:pre-wrap">{statement}</p>{#if error}<div class="notice error mt" role="alert">{error}</div>{/if}{#if receiptNotice}<div class="notice info mt" role="status">{receiptNotice}</div>{/if}<div class="inline-actions mt">{#if receipt.receiptToken}<button class="btn primary" disabled={downloading} onclick={downloadReceipt}><Icon name={downloading?'refresh':'download'} size={16} class={downloading?'spin':''}/>{downloading?'Wird geladen …':'PDF-Eingangsnachweis abrufen'}</button>{/if}<button class="btn" onclick={()=>window.print()}>Diese Bestätigung drucken</button></div></div></section>{:else}<form class="panel" onsubmit={send}><div class="panel-body">{#if error}<div class="notice error" role="alert">{error}</div>{/if}<div class="field-grid"><div class="field full"><label for="withdrawal-reference">Vertrag oder Vorgang *</label><input id="withdrawal-reference" bind:value={reference} required minlength="2"/><span class="field-help">Angebots-, Auftrags- oder Vertragsnummer. Falls sie unbekannt ist: Vorhaben und Datum möglichst genau beschreiben.</span></div><div class="field"><label for="withdrawal-name">Vollständiger Name *</label><input id="withdrawal-name" bind:value={personName} autocomplete="name" required minlength="2"/></div><div class="field"><label for="withdrawal-email">Ihre E-Mail-Adresse *</label><input id="withdrawal-email" type="email" bind:value={email} autocomplete="email" required/><span class="field-help">Damit Schubert Ihre Erklärung zuordnen und Sie zur Bearbeitung erreichen kann.</span></div><div class="field full"><label for="withdrawal-statement">Ihre Widerrufserklärung *</label><textarea id="withdrawal-statement" bind:value={statement} required minlength="5"></textarea><span class="field-help">Beschreiben Sie eindeutig, welchen bezeichneten Vertrag Sie widerrufen möchten.</span></div><label class="check-field full" style="grid-column:1/-1"><input type="checkbox" bind:checked={confirmed} required/><span>Ich möchte die oben angegebene Erklärung an Schubert übermitteln.</span></label></div></div><footer class="panel-footer"><span class="small muted">Der Eingang wird nach erfolgreicher Speicherung bestätigt.</span><button class="btn primary" disabled={busy||!confirmed||!key}>{busy?'Wird übermittelt …':'Widerrufserklärung übermitteln'}<Icon name="arrow" size={16}/></button></footer></form>{/if}</main></div>
<style>.withdrawal-content{max-width:850px;margin:0 auto;padding:48px 25px 90px}.withdrawal-content textarea{min-height:160px}@media(max-width:760px){.withdrawal-content{padding:30px 20px 70px}.portal-topbar{align-items:flex-start;gap:20px}.portal-topbar>.small{font-size:11px;max-width:120px;text-align:right}}@media print{.withdrawal-content .btn{display:none}.withdrawal-content{padding:20px}.portal-topbar{padding:20px}}</style>
